function dynamicsView(){
 const reports=currentObjectId?(objectAnalyticsData||[]).filter(x=>+x.id===+currentObjectId&&x.reportData).map(x=>x.reportData):[{workDays:arr("workDays")}],groups={};
 for(const r of reports)for(const x of r.workDays||[]){if(!x.date&&r.reportDate)x.date=r.reportDate;const t=arr("tasks").find(t=>(t.type||"")===(x.type||"")&&(t.code||"")===(x.code||"")),unit=t?.unit||x.unit||"";const k=(x.type||"—")+"|||"+(x.code||"—")+"|||"+unit;groups[k]??={type:x.type||"—",code:x.code||"—",unit,daily:{}};const d=x.date||r.reportDate;if(d)groups[k].daily[d]=(groups[k].daily[d]||0)+qtyOf(x)*rowPer(x)}
 const dates=[...new Set(reports.map(r=>r.reportDate).filter(Boolean))].sort(),endRaw=dates.length?new Date(dates[dates.length-1]+"T12:00:00"):new Date(),days=[];for(let i=20;i>=0;i--){const d=new Date(endRaw);d.setDate(endRaw.getDate()-i);days.push(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`)}
 const cards=Object.values(groups).map(g=>{const vals=days.map(d=>g.daily[d]||0),max=Math.max(1,...vals),sum=vals.reduce((a,b)=>a+b,0);return `<div class="chartBox dynamicsCard"><div class="dynHead"><div><h3>${esc(g.type)}</h3><span>${esc(g.code)} · ${esc(g.unit)}</span></div><div><small>За 21 день</small><b>${fmt(sum)} ${esc(g.unit)}</b></div></div><div class="bars">${days.map(d=>{const v=g.daily[d]||0;return `<div class="barCol" title="${esc(d)}: ${fmt(v)}"><span>${v?fmt(v):""}</span><i style="height:${v?Math.max(4,v/max*100):1}%"></i><small>${d.slice(8,10)}.${d.slice(5,7)}</small></div>`}).join("")}</div></div>`}).join("");
 return card("Динамика выполненных работ по объекту",cards||'<div class="empty">Пока нет выполненных работ по объекту.</div>')
}
function ganttView(){
 const today=state.reportDate||localDateKey();
 const cards=arr("deadlines").map(dl=>{const t=arr("tasks").find(x=>(x.type||"")===(dl.type||"")&&(x.code||"")===(dl.code||""))||{},start=dl.start,end=dl.end||dl.date;if(!start||!end)return"";
 const s=new Date(start+"T00:00:00"),e=new Date(end+"T00:00:00"),td=new Date(today+"T00:00:00");if(!Number.isFinite(s.getTime())||!Number.isFinite(e.getTime())||e<s)return`<div class="gantt behind"><b>Проверьте даты: ${esc(start)} — ${esc(end)}</b></div>`;
 const span=Math.max(86400000,e-s),timePct=Math.max(0,Math.min(100,(td-s)/span*100)),vol=taskVol(t),act=doneFor(dl.type||"",dl.code||""),factPct=vol?Math.min(100,act/vol*100):0,expected=vol*timePct/100,delta=factPct-timePct,stateCls=act+1e-9<expected?"behind":act>expected?"ahead":"ontime",status=stateCls==="behind"?"Отставание":stateCls==="ahead"?"Опережение":"По графику";
 return `<div class="gantt ${stateCls}"><div class="gHead"><div><b>${esc(dl.type||"Работа")}</b><small>${esc(dl.code||"")}</small></div><span>${status}</span></div><div class="gProgressNumbers"><div><small>План на дату</small><b>${fmt(timePct)}%</b></div><div><small>Фактически</small><b>${fmt(factPct)}%</b></div><div><small>Отклонение</small><b>${delta>0?"+":""}${fmt(delta)}%</b></div></div><div class="gTimeline"><div class="gPlan" style="width:${timePct}%"></div><div class="gFactNew" style="width:${factPct}%"></div><i style="left:${timePct}%"></i></div><div class="gDates"><small>${start}</small><small>Отчёт: ${today}</small><small>${end}</small></div><div class="gMeta">Объём: ${fmt(vol)} ${esc(t.unit||"")} · Выполнено: ${fmt(act)} ${esc(t.unit||"")} · План на дату: ${fmt(expected)} ${esc(t.unit||"")}</div></div>`}).join("");
 return card("Сроки выполнения",cards||'<div class="empty">Добавьте сроки с датами начала и окончания.</div>')
}
function calendarView(){
 const work=new Set(arr("workDays").filter(x=>x.date&&qtyOf(x)>0).map(x=>x.date)),acted=new Set(arr("actedDays").map(x=>typeof x==="string"?x:x.date).filter(Boolean)),all=[...work,...acted].sort();if(!all.length)return card("Календарь работ",'<div class="empty">Нет дат.</div>');
 const last=state.reportDate||all.at(-1),ym=last.slice(0,7),y=+ym.slice(0,4),m=+ym.slice(5,7)-1,days=new Date(y,m+1,0).getDate(),off=(new Date(y,m,1).getDay()+6)%7,names=["Пн","Вт","Ср","Чт","Пт","Сб","Вс"];
 let cells=names.map(x=>`<b class="calHead">${x}</b>`).join("")+"<i class='calEmpty'></i>".repeat(off);
 for(let d=1;d<=days;d++){const ds=ym+"-"+String(d).padStart(2,"0"),w=work.has(ds),ac=acted.has(ds);cells+=`<div class="calDay ${w&&ac?"both":w?"work":ac?"acted":""}"><b>${d}</b></div>`}
 return card("Календарь работ / актированных дней",`<div class="calendar">${cells}</div><div class="legend">Работы — зелёный · Актированный день — красный</div>`)
}

function fmt(v){const x=n(v);return x.toLocaleString("ru-RU",{maximumFractionDigits:2})}
