 return card("Фотоотчёт",`<div class="photoCollage">${arr("reportPhotos").map((p,i)=>`<img data-lightbox="${i}" src="${typeof p==="string"?p:(p.data||p.url||"")}" alt="Фото ${i+1}">`).join("")}</div>`)
