async function openObject(id){if(currentDailyReportId)await saveNow();currentObjectId=+id;if(!currentObjectId)return;const project=await Smetriqo.loadObject(currentObjectId)||{},days=await Smetriqo.dailyReports(currentObjectId)||[];dailyReportList=days;const latest=days[0]?await Smetriqo.loadDailyReport(days[0].id):{};currentDailyReportId=days[0]?.id||null;currentReportId=null;state=mergeProjectDaily(project,latest);if(!state.object)state.object=objectList.find(x=>x.id===currentObjectId)?.name||"Объект";hydrateRowUnits();view="objectHome";render()}
